quests[34650] = { id = 34650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderlord Invasion", description = "Our shadow hunters spotted some of dem Thunderlord gettin' ready to attack us, commanda!\n\nWe should be gettin' ready for an invasion!" }
quests[34651] = { id = 34651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Dagg Found at Grom'gar" }
quests[34652] = { id = 34652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Savage Clam" }
quests[34653] = { id = 34653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arakkoa Exodus", description = "I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.", completion = "<The arakkoa merchant looks you up and down.>\n\nWell-equipped, aren't we? Azik is betting you are someone of importance to your people.\n\nCome closer, friend. Speak with me for just a moment.", objectives = "Speak with Azik in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34654] = { id = 34654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Dagg Found at Daggermaw Ravine" }
quests[34655] = { id = 34655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadows of Skettis", description = "My people flee our homeland in droves. I sell trinkets to ease the journey.\n\nBut I see that you are not interested in trinkets... No, what you seek are answers.\n\nSkettis lies just ahead. Once a great city built by Terokk as a refuge for the unwanted. Now a ruined slum.\n\nAn old storyteller lives there - a scrollkeeper named Reshad. Find him and speak these words: \"Shadows gather.\" He will know you are a friend.\n\nNow go. Your presence is bad for business.", progress = "If you're here for some kind of legendary tome of unthinkable power, I'm sorry to disappoint you. I am merely a keeper of history.\n\nI am also very busy at the moment.", completion = "Azik must have seen something in you. I will trust his judgment, for n-\n\n<Reshad is interrupted as a warm gust of wind surges through the hut.>\n\nOh dear... they've arrived.", objectives = "Speak the password to Reshad in Skettis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34656] = { id = 34656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden in Plain Sight", description = "<Reshad begins hastily stuffing scrolls into his robes.>\n\nI thought I would have more time to prepare! There are powerful relics hidden out there in Skettis - if I leave without them, I may as well have died.\n\nThe first is a pair of wingblades being held by an effigy near the front gate. You likely walked right past them on your way in.\n\nAnother effigy on the east side of the ruins bears a white mask over its face.\n\nBring those relics to me, and their secrets shall be yours.", progress = "Wingblades forged in the name of a sun god to bring freedom and glory to her children.\n\nA mask worn by a great king who would walk among his people in disguise to know their true nature.", completion = "Who would expect to find these treasures draped over straw dolls, left to bake in the sun? Sometimes the best place to hide precious things is in plain sight.", objectives = "Retrieve the Weathered Wingblades and Ragged Mask.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34657] = { id = 34657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adherents of the Sun God", description = "The arakkoa from Skyreach are all ruled by the Adherents of Rukhmar. They revile those of us who bear the Curse of Sethe, and decree that we must be purged in the name of their sun god.\n\nSoon their gaze will turn to lands beyond Arak.\n\nChallenge their warriors. Buy me time to prepare my escape, and help me set into motion their downfall.", progress = "Skettis will fall today. Neither of us can change that.\n\nWe need only to send them a message: we will not die quietly.", completion = "Azik was right to guide you to me. If you were coming to help Skettis, we needed to meet.\n\nAnd if you were coming to attack us, well, I'd be dead either way, wouldn't I?\n\n<Reshad lets out a cawing laugh and stuffs another scroll into his robes.>\n\nThere, that's nearly everything.", objectives = "Slay 8 Adherent Bladewings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34658] = { id = 34658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders From On High", description = "The Adherents of Rukhmar are the ruling body atop the spires. Their influence is absolute. Their proclamations taken as the will of Rukhmar Herself.\n\nThe herald leading this purge is surely carrying out such orders - likely no more than a list of names and places they plan to erase.\n\nThat list would prove invaluable in the days to come. Acquire it for me, and shut that herald up!", progress = "<Reshad fastens another scroll to Percy, who squawks meekly in protest.>\n\nOh, stop whining.", completion = "Ah yes, there's my name at the top of the list. And a few Talonpriests from the Shadowglade as well.\n\nThey fear the return of Terokk, as they should.", objectives = "Loot the Adherent Proclamation from Sun-Sage Rathyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34659] = { id = 34659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crone", progress = "You would be wise to turn back, traveler.", completion = "I will point you in the right direction, but I cannot guarantee you'll survive the trip.\n\nKah-hah haha!", objectives = "Speak the password to Ornekka at Crow's Crook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34660] = { id = 34660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorkra's Fall" }
quests[34661] = { id = 34661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drudgeboat", description = "[TEMP]<The torn scroll outlines the schedule of several upcoming Frostwolf prisoner arrivals.>\n\n<It appears that they are being shipped in by boat. This could be your method of escape. Khadgar will want to see this.>", objectives = "Bring the Drudgeboat Schedule to Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34662] = { id = 34662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Trials: Crushmaul", description = "So you want to fight in the Ring of Trials do you? It's your funeral, bub!\n\nYour first fight is against an exceptionally large and angry ogre named Crushmaul. That's not all though, you'll have to take out his armored boar companion too; Crushmaul never goes into the ring without him!\n\nI hope your affairs are in order, because the last gladiator that fought Crushmaul went home in a body bag...\n\nI'm counting on you! Get your ass inside the arena and speak with my associate Guzrug to start the fight!", progress = "What are you waiting for? Get in the ring and start spilling blood!", completion = "Whoa! I couldn't tell if that was Porkchop squealing in there or if you had Crushmaul crying like a little baby!\n\nYou've got talent, kid!\n\nHere's your cut of the profit, but why stop there? Together we can make a mountain of gold!", objectives = "Defeat Crushmaul in the Ring of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34663] = { id = 34663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Trials: Raketalon", description = "You may have defeated Crushmaul, but the party's over now...you've got another fight!\n\nThe Highmaul take gladiatin' seriously; so when they built the Ring of Trials, they searched far and wide for the most brutal creatures they could find!\n\nYou're up against a dread raven the ogres are calling Raketalon! I'm telling you, {name}, something about that bird just ain't right...I think it truly enjoys the act of killing!\n\nRaketalon toyed with the last gladiator for hours before eating him.\n\nTry not to die!", progress = "What are you waiting for? Get in the arena and start spilling blood!", completion = "You did it, {name}! Raketalon has actually been defeated!\n\nI'd never have believed it if I hadn't seen it with my very own two eyes. You've got a fire in your belly and dollar signs in your eyes, kid!\n\nHere's your cut of the profit, but don't stop now! You're on a roll!", objectives = "Defeat Raketalon in the Ring of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34664] = { id = 34664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Trials: Hol'yelaa", description = "You won your first two fights, but it's only going to get tougher from here!\n\nYour next fight is against Hol'yelaa, a former rangari who is as crazy as they come.\n\nNo, really... Hol'yelaa is bonkers!\n\nYears ago, while on a scouting mission, he single handedly saved his entire rangari unit from a pack of Garn. But something inside of him snapped....\n\nIt wasn't long before Hol'yelaa went completely marbles and turned on his own unit!\n\nAlright, the pep talk is over! Get in there and kick some ass!", progress = "What are you doing standing around? Get in the arena and spill some blood!", completion = "Watching you fight in the arena is like witnessing an artist create a masterpiece!\n\nWell, a masterpiece of blood and shattered bones... but hey, everyone's got to be good at something right?\n\nHere's your cut of the profit! That fight was so good I actually thought about giving you a bonus!", objectives = "Defeat Hol'yelaa in the Ring of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34665] = { id = 34665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Trials: Captain Boomspark", description = "You've been making a name for yourself in the arena, {name}!\n\nDon't get too excited though...fame has its consequences! You've been challenged by an up-and-coming gladiator who is looking to make a name for himself, sound familiar?\n\nYour next fight is against Captain Boomspark, a mercenary who came here to fight for the Iron Horde.\n\nThe Iron Horde ain't exactly throwing piles of gold around, so now he's here!\n\nHe's got a shredder, so watch out for the blades... and the fire too... especially the fire!", progress = "What are you doing standing around? Get in the arena and spill some blood!", completion = "I ain't ever seen anybody dismantle a shredder quite like that before!\n\nYou've made me a lot of money, {name}! Only the best gladiators survive this long in the arena; and yet, even with that in mind, there's still something different about you...\n\nIt's your eyes...they look as if they've stared death in the face a thousand times and never even blinked.\n\nTake your cut of the profit and rest up, the biggest fight is still ahead!", objectives = "Defeat Captain Boomspark in the Ring of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34666] = { id = 34666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring of Trials: Roakk the Zealot", description = "The final match is at hand, {name}! You've decimated all of the best challengers! There's nowhere to go from here but the very top...the reigning champion of the Ring of Trials!\n\nThe current champ is an arakkoa named Roakk the Zealot. Roakk is a lunatic! He says he's on some divine crusade for the sun or something.\n\nCrazy or not, he's one of the most dangerous fighters I've ever seen and has even fought in the Highmaul Coliseum!\n\nI'm not going to lie, you're probably going to die in there...good luck!", progress = "What are you doing standing around? Don't you hear the crowd screaming?\n\nThere's a championship waiting on you!", completion = "Long live the champ! I knew you could do it!\n\nCould you hear the roar of the crowd in there? It shook the arena like thunder!\n\nThis is only the beginning! The Highmaul Coliseum awaits, and as the champion of the Ring of Trials you'll be expected to make an appearance!", objectives = "Defeat Roakk in the Ring of Trials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34667] = { id = 34667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Court of Souls" }
quests[34668] = { id = 34668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Talonpriest Zorkra" }
quests[34669] = { id = 34669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Lumber", description = "xxxxxx" }
quests[34670] = { id = 34670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professional Processing", description = "Hey boss! We got ourselves quite a lot of raw materials ripe for some professional processing... if you know what I mean. Time to get us a building that can help put those materials to good, weaponizing use.\n\nI got a few extra plans we might be able to use to get you started, but you gotta' pick which one to make. Once you choose, talk to Rezlak and get construction started on it.", objectives = "Learn a Profession Building Blueprint from Gazlowe and then have Rezlak begin construction of the building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34671] = { id = 34671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shirzir" }
quests[34672] = { id = 34672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of Aku'mai", description = "We barely escaped the Twilight's Hammer sacrificial altar, but there are others who need help deeper within these caves. If these cultists complete their blood ritual, they will unleash Aku'mai the Devourer onto the world. You cannot let this happen.", progress = "Hurry, {name}! Aku'mai must be stopped before he devours our world!", completion = "That was incredible, {name}! The Old Gods will think twice before trying to crawl out of their pit again.", objectives = "Kill Aku'mai the Devourer", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34673] = { id = 34673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of Aku'mai", description = "We barely escaped de Twilight's Hammer sacrificial altar, but others be needin' help deeper in. If de blood ritual be complete, they be unleashin' Aku'mai da Devourer. Don let this be happenin', mon.", progress = "Move, {name}! Aku'mai be wantin' to devour de world!", completion = "Dat was amazin', {name}! De Old Gods be thinkin' twice before tryin' to take anudder bite outta you, mon.", objectives = "Kill Aku'mai the Devourer", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34674] = { id = 34674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Fight to Nagrand", description = "**Eyes Only -- Commander {name}**\n\nWith the fall of the rangari base at Telaar, Vindicator Yrel, recommended we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that a new outpost is nearly complete. He has indicated that they are ready to receive you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, <sir/ma'am>.\n\n-- Bodrick Grey, SI:7", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>", objectives = "Speak with Lieutenant Balfor at the caravan in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34675] = { id = 34675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded... west.\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", completion = "Commander {name}. It's good to see you. We have much to discuss.\n\nThe situation in Nagrand is rapidly deteriorating. We've lost Telaar.\n\nTo make matters worse, Grommash has named Garrosh Hellscream the new warlord of the Warsong clan.", objectives = "Speak with Rangari D'kaan at Telaari Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34676] = { id = 34676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", completion = "I won't waste any of your time, sir. Let us discuss strategy.", objectives = "Speak to Dungar Longdrink to secure a flight to Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34678] = { id = 34678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up and Running", description = "The Warsong struck us hard. We lost Telaar, but we have a rare opportunity to strike at the heart of the Warsong.\n\nWe need your wisdom and leadership to pull it off, {name}.\n\nFirst though, we're going to get our survivors out of Telaar. My rangari are ready to strike. We just need to get you to them.\n\nThaelin has a copter that can get you to them. Unfortunately, his hands are full just trying to keep the infernal thing running.\n\nHelp him get it up and running?", progress = "{name}, I can't tell you how great it is to see you.", completion = "For me? Really you shouldn't have.\n\nOkay, this should do it.\n\nI hope.", objectives = "Collect the Assorted Engineering Parts, Prop Rotor, and Transmission Flywheel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34679] = { id = 34679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Stables Tracking Event" }
quests[34680] = { id = 34680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Workshop Tracking Event" }
quests[34681] = { id = 34681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Matter of Strategy", description = "Da Iron Horde have proved themselves worthy foes.\n\nThey managed to get their fleet movin' to Talador from Gorgrond without my spies seein' a thing. Talador be a crossroads for the whole continent. We can't let them have it.\n\nDon't worry boss, we got a plan. Foreman Grobash be settin' up an outpost for our forces as we speak. They be ready for you when you arrive, commander.", completion = "Your will be done. I require your advisement, commander.", objectives = "Speak to Bron Skyhorn to secure a flight to Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34682] = { id = 34682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Surprise Party", description = "There weren't many survivors of the Warsong attack. The few remaining rangari have gone up to one of the bluffs overlooking Telaar.\n\nThe rangari are waiting for you. They're planning a surprise counter-attack.\n\nMy copter's taken a beating. The auto-pilot's set to take you up there. I think she's got one last trip in her.\n\nMaybe.", completion = "We've been expecting you, commander.\n\nThe situation is grim, but doable with your help.", objectives = "Use Thaelin's Copter to get up to the Rangari Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34683] = { id = 34683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Ahead", description = "Boss, Durotan set off with Draka and Gazlowe to track da Iron Horde's movements along da coast.\n\nDey waitin' for ya on the cliffs to da northwest.", completion = "Ah, {name}. I recognized your scent, friend. We have been waiting for your arrival to begin our task.", objectives = "Speak to Durotan in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34684] = { id = 34684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Ahead", description = "Commander, Vindicator Maraad took Yrel and Thaelin Darkanvil just up to the road from here to track the Iron Horde's forces in the forest.\n\nThey are already at work formulating a strategy to stop their operations. They await your arrival on the cliffs to the northwest.", sourceObjective = "Speak to Vindicator Maraad in Talador.", sourceObjectiveStatus = "unverified-source-field" }
quests[34685] = { id = 34685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As the Smoke Rises", description = "Aruuna burns.\n\nThe arakkoa swooped down from their spires and are turning everything to ash. Draenei, talbuk, even orc; they care not for allegiances. They merely want to watch the world burn.\n\nI barely escaped with my life, but my best friend, Barum, stayed behind to find his daughter. The others all say you are a great champion. Please, I beg of you, go to Aruuna and find them.", completion = "Kalaam sent you? By the Light, I knew I could count on him!", objectives = "Find Crystal-Shaper Barum near Aruuna in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34690] = { id = 34690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just the Beginning", description = "It... is over.\n\nWe should return to your outpost and discuss our next course of action. There are innocent people in danger across all of Talador that need our help.\n\nI will have Khadgar open a portal for us. Let us save our words for now.", sourceObjective = "Speak to Yrel in Talador.", sourceObjectiveStatus = "unverified-source-field" }
quests[34691] = { id = 34691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just the Beginning", description = "I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right.\n\nWe should return to your outpost and discuss our next course of action. There is nothing left for us here.\n\nI will ask the human to open a portal for us. We shall speak again there.", sourceObjective = "Speak to Durotan in Talador.", sourceObjectiveStatus = "unverified-source-field" }
quests[34692] = { id = 34692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delegating on Draenor", description = "There is more work to do on Draenor than we can possibly handle by ourselves. We need to start delegating.\n\nA group of night elves need a champion at Starfall Outpost.\n\nQiana is a perfect fit for this mission.", progress = "You can use the Command Table to assign missions to your followers.", completion = "This is a good start, but we will need more champions to deal with the trials that lay ahead.", objectives = "Use the Command Table to send Qiana Moonshadow on a mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34696] = { id = 34696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lady of Light", description = "{name}, yes? You are the one in charge here? I am Knight-Lord Dranarus, at your service.\n\nLady Liadrin has responded to a suspected demon presence near Auchindoun, southwest of here. She has asked specifically for your assistance in ensuring Auchindoun does not fall into Gul'dan's hands.\n\nIf you could set forth at your nearest convenience, I am sure the Lady would be most grateful.", completion = "We'll have to catch up later. We have bigger problems!", objectives = "Speak to Lady Liadrin at the Burning Front in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34697] = { id = 34697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rediscovered Legend", description = "If your troops are going to learn to fight people you better get people to fight! And they better be good.\n\nEver hear of Kash'drakor?\n\nHe's a big famous Frostwolf orc warrior type that tried to kill us Skulls. He would have won too, if the ogres hadn't snatched him.\n\nTo the north is the Stonemaul Arena where they took him and a bunch of other big bad mean fighter gladiators.\n\nIf you can find a way to free them, they could be the best trainers you could hope for.", completion = "The Laughing Skull sent you? If they were any other clan I would find that ironic.\n\nI am Kash'drakor, hero of the Frostwolf clan, and champion of the slave pits of Stonemaul.\n\nAnd yet, despite all these titles, I need your help.", objectives = "Find Kash'drakor near the Stonemaul Arena in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34698] = { id = 34698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slave Hunters", description = "Anytime a gladiator escapes Stonemaul, they send their hardened slave hunters after us.\n\nI consider myself a capable warrior, years of surviving in an arena have taught me that.\n\nBut these slave hunters keep pendants magically tethered to the slaves. With these pendants they can track us down anywhere we go, and kill us in our sleep or when our guard is down.\n\nI have no right to ask this, but can you enter Stonemaul and retrieve these pendants?", progress = "Have you the pendants?", completion = "You have shown more honor in this one act than I have seen in many years.\n\nWhen this is over, I will swear my axe to your forces and pass my knowledge on to your troops.", objectives = "Collect the Pendants of Brol, Krag, and Mol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34699] = { id = 34699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Gladiators", description = "When we fled Stonemaul, we had to leave others behind.\n\nIf we try to rescue them and are recognized, the ogres will know our purpose, and the first thing they will do is kill our friends.\n\nThe ogres do not know you, which might give you a fighting chance.\n\nEnter Stonemaul, find the other gladiators, and release them from their bonds. Do this and you will have our loyalty.", completion = "Thank you, strange one. Now we are free to split that chieftain Kor'gall wide open!", objectives = "Rescue gladiators Bruto, Y'kish, and Pitfighter Vaandaam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34700] = { id = 34700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nazgrel", description = "Escaping Stonemaul was the easy part. The ogre filth that rule the pits still have my son.\n\nFor a while they used him as leverage to ensure I would fight in their arenas. But now that I have escaped they will try to train him to replace me.\n\nPlease, rescue my son. If they see me they will kill him instantly.", completion = "This deed will never be forgotten as long as I or my son live. You have my gratitude, hero, and my loyalty.", objectives = "Rescue Nazgrel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34701] = { id = 34701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaker for the Dead", description = "Oh, praise the Light, you're here! Exarch Maladaar asked for me to find you.\n\nWe need your help. Auchindoun is under attack by demons!\n\nGo to the Burning Front to the southwest as soon as possible! You're one of the few people he trusts to help lead the defense.", completion = "I will not allow a single demon to step foot inside Auchindoun. You will help me ensure that does not happen.", objectives = "Speak to Exarch Maladaar at the Burning Front in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34702] = { id = 34702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krav'ogra", description = "Stonemaul has chieftain, and it has slavemaster. Today, we kill both.\n\nFirst, Slavemaster Ok'mok. Me fight in arenas since me your size. Me know cruelty. Slavemaster Ok'mok is cruelty.\n\nWant to be true gladiator? Go to Stonemaul Arena, bang challenge gong in center of arena, and face beasts of slavemaster.\n\nMaybe you make Ok'mok so mad he jump down himself to kill you. If he do, kill him instead.", completion = "Me watch you from afar. Me like your fighting skills, show much promise.", objectives = "Slay Slavemaster Ok'mok by using the Challenge Gong in Stonemaul Arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34703] = { id = 34703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Axe of Kor'gall", description = "Time for vengeance! We are going to kill Kor'gall and you are going to take his axe.\n\nShatter this feeble barrier, follow the bridge beyond until you reach the chieftain's throne.\n\nYou freed us, so the honor of first blood is yours. Strike the first blow and we will join you in the cutting.", progress = "Kor'gall has ruled uncontested for far too long.", completion = "This blade has caused enough pain and suffering for one lifetime. We shall see to it that it is properly disposed of.", objectives = "Kill Kor'gall and retrieve his axe, Serathil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34704] = { id = 34704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rediscovered Legend", description = "This Sparring Arena is a good start, but we will need trainers to help mold your forces into worthy fighters.\n\nThere has been a reported spotting of a draenei to the west who matches the description of Akaani.\n\nThis is interesting, as we all believed her dead. She was one of the finest warriors the draenei have ever fielded and a master of nearly any weapon forged or found.\n\nCommander, you could not ask for a more skilled trainer. I advise seeking her out, if it is really her...", completion = "You do not have the look of a Stonemaul bounty hunter.\n\nWe escaped the clutches of their vile arena but at a heavy cost. We were forced to leave too many allies behind and too many ogres breathing.\n\nWe could use a fresh face, one that is unknown to the ogres.", objectives = "Find Gladiator Akaani near Stonemaul Arena in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34705] = { id = 34705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Shadowmoon Intro" }
quests[34706] = { id = 34706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Together", description = "Your work is done here, {name}. I will stay here for now and help clean up any remaining demons.\n\nYou should return to your outpost and let Dranarus know of our success. He can relay that information to Azeroth.", completion = "Lady Liadrin was indeed wise in choosing you. I will let Vol'jin know of your victory immediately.", objectives = "Speak to Knight-Lord Dranarus at Vol'jin's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34707] = { id = 34707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Come Together", description = "Gul'dan and his cronies would do well to remember this day. We Auchenai are not to be trifled with.\n\nYou should inform Vindicator Icia in your outpost of our success. She can reach out to the scattered refugees and their families.", completion = "I will gather any remaining survivors so we can rebuild what we have lost.\n\nThank you.", objectives = "Speak to Vindicator Icia at Fort Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34708] = { id = 34708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Jehil the Climber", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent." }
quests[34709] = { id = 34709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Bit Counts", description = "The Jorune Mine, west of here, needs your help!\n\nMy good friend Ageilaa sent me to look for help. Exarch Maladaar sent over what vindicators he could spare, but it isn't enough!\n\nWill you go to the mine and help us? We need the crystals from the mine to create more defenses like the crystals you see on the Burning Front.", completion = "Aeun sent you? Help has arrived!", objectives = "Speak to Ageilaa at the Jorune Mine in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34710] = { id = 34710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Bit Counts", description = "Manduil Skycaller was sent on a sensitive mission to Jorune Mine, but he hasn't returned for hours.\n\nI suspect he requires assistance. I will let him brief you on the situation when you find him, but he is likely deep within the mine.\n\nYou should report to Ageilaa, a local draenei miner who has agreed to cooperate with us in exchange for helping her regain control of the mine.", completion = "Aeun sent you? Help has arrived!", objectives = "Speak to Ageilaa at the Jorune Mine in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34711] = { id = 34711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Due Cause to Celebrate", description = "Shall we return to your outpost? It would be a much better - and safer - place to celebrate.\n\nI'll teleport us there.", completion = "We can finally connect your tower to the ley line network with this crystal.\n\nI also edited your blueprint so you can actually read the thing. Should make building another one much easier.", objectives = "Speak to Magister Serena at Fort Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34712] = { id = 34712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Due Cause to Celebrate", description = "This isn't exactly my idea of the best place to talk.\n\nShall we return to your outpost? It will be a much better place to celebrate.\n\nI'll teleport us there.", completion = "With this crystal, we can connect your tower to the ley line network at last!\n\nI also made some modifications to your blueprint that should make it much easier to build another tower in your garrison.", objectives = "Speak to Magister Krelas at Vol'jin's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34713] = { id = 34713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gronnstalker's Cache" }
quests[34714] = { id = 34714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfire Ridge: (RRP) - Treasure - Pale Leather Cache" }
quests[34715] = { id = 34715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Shamanstone Summons" }
quests[34716] = { id = 34716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mo'mor Might Know", description = "We know the Warsong packleader that attacked the caravan is in Telaar. She has the blueprints.\n\nWe don't know where she is down there, but there's one who might.\n\nVindicator Mo'mor was last seen alive, but taken prisoner. If he's still alive, he might know where the blueprints are.", completion = "Please forgive me. I'm in no condition to stand, commander.", objectives = "Find Vindicator Mo'mor in Telaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34717] = { id = 34717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Just Arrowhead", description = "It goes without saying that we'll help you kill any of the Warsong out in the open down there.\n\nYou just start the fight, and we'll end it with extreme prejudice.", completion = "That bit of justice is sure to have lifted the spirits of my rangari.\n\nLosing Telaar and many of our friends has taken a heavy toll.\n\nThank you, commander.", objectives = "Kill 15 Warsong forces at Telaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34718] = { id = 34718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Others", description = "There are yet a few survivors. I saw them pile onto Arbiter Khan during the fighting.\n\nMore importantly, I can hear little Isel's sobs. She's nearby. I hope her mother is still alive.\n\nYour dwarf friend, Hansel, came in to try to rescue us. He thought he could take the Warsong on his own. I'm afraid I don't know what happened to him.", completion = "Khan! No!... he just received his promotion. His whole life ahead of him and now, nothing.\n\nThank you for getting the others out. Light be... nevermind.", objectives = "Rescue Arbiter Khan, Caregiver Felaani & Isel, and Hansel Heavyhands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34719] = { id = 34719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... and My Hammer", description = "When they captured me, the Warsong took my hammer. Will you help me to recover it?\n\nI ask only because it's a holy relic. It should be taken from these orc dogs for no other reason than to return it to Auchindoun.\n\nPerhaps then, a worthy vindicator of the Light will take it up to smite the enemies of the draenei.", progress = "I'm having trouble seeing. I may not have long.", completion = "Thank you for this kindness, {name}. Perhaps I can still salvage some scrap of honor.", objectives = "Retrieve Mo'mor's Holy Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34720] = { id = 34720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Just Arrowhead", description = "It goes without saying that the Warsong in Telaar need to be dealt with. Rangari Ogir and his forces on the overlook will help you kill any of the orcs that are out in the open.\n\nYou just start the fight, and they'll end it with extreme prejudice.", completion = "That bit of justice is sure to have lifted the spirits of my rangari.\n\nLosing Telaar and many of our friends has taken a heavy toll.\n\nThank you, commander.", objectives = "Kill 15 Warsong forces at Telaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34721] = { id = 34721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek Out the Seer", description = "We've been watching you, {name}.\n\nSeer Malune, keeper of memories, has requested an audience with you, adventurer.\n\nShe has long foretold the coming of a great hero to destroy the lurking shadow. We believe you are that hero.\n\nCome to Duskfall Island, not far southeast of here, and fulfill your destiny.", completion = "I am Seer Malune, the great keeper of memories. It is an honor to finally meet you.", objectives = "Speak to Seer Malune on Duskfall Island in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34722] = { id = 34722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durotan Been Askin' For Ya", description = "Durotan been askin' for ya, mon.", completion = "You did well against a coordinated Thunderlord attack, {name}.", objectives = "Speak with Durotan at your Garrison", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34723] = { id = 34723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ironfist Harbor" }
quests[34724] = { id = 34724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten Caves" }
quests[34725] = { id = 34725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sea Hydra" }
quests[34726] = { id = 34726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Spider Broodmother" }
quests[34727] = { id = 34727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sea Lord Torglork" }
quests[34728] = { id = 34728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shimmer Moor" }
quests[34729] = { id = 34729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of Na'Shra", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", completion = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34730] = { id = 34730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of Lokra", description = "You have done me a great service. This blade is as much yours as it is mine.\n\nI offer you this blood oath: I shall serve your cause and lend my knowledge of blades and mining to your forces.\n\nWill you accept it?", completion = "Commander {name}, Your mastery over the battlefield is astounding. If my people are to survive the coming conflict we will need more of our own people skilled in such warfare.\n\nIf you will have me, I would like to join your forces for a time. I wish to learn from you so that I might teach others in my clan.\n\nWill you accept my axe?", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34731] = { id = 34731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oath of Shadow Hunter Rala", objectives = "My sista have other duties, but I have leave of ol' Vol'jin to extend my services to you.\n\nYa proved your worth, and did a task that needed doing.\n\nI be followin' ya, boss-mon, if ya be willing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34732] = { id = 34732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mulverick's Offer of Service", objectives = "Well, hero, I owe you both my life and my honor. I ask that you allow me to repay this debt by serving under your command.\n\nYou will find that I am a fearsome hunter. I have also mastered the art of riding the rylaks, which few among the Frostwolves can claim.\n\nWill you accept my service?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34733] = { id = 34733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Services of Dagg", objectives = "Gonna have to ask demself, \"Did Dagg get catched or did Dagg catched dem?\"\n\nBig hero been blowin' Dagg's cover! But you special, Dagg tinks. Dagg is master of dis guys and want to join you.\n\nDagg is unanimous in dis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34734] = { id = 34734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Loyalty of Olin Umberhide", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34735] = { id = 34735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderlord Invasion!", description = "Sir! Scouts have spotted Thunderlords approaching from the east.\n\nThe men are armed and ready. We'll mount defensive positions as soon as you take the field.", objectives = "Speak with Legionaire Grimjaw in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34736] = { id = 34736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Be Needin' Supplies", description = "Commander, our forces are not prepared for frost fightin'. I took da liberty and sent some of our shadow hunters north to establish a supply base. \n\nYa might want to be headin' up dere and see what they be up to. Look for a hollow between the Crackling Plains and the Savage Crag.", completion = "Eh dere, boss-mon! Watch ya step. Da ground be cracklin' and breakin' everywhere.", objectives = "Speak with Shadow Hunter Rala at Darkspear's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34737] = { id = 34737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masters of Shadow", description = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding.\n\nAll of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me.\n\n<Luuka takes a deep breath.>\n\nUngra, Gurran, and... umm... oh! Ankova.\n\nWill you protect me from them?", progress = "How goes your mission?", completion = "Well done.\n\nBe ready to move. We may have had the element of surprise within this cave, but our advantage is fleeting.", objectives = "Slay Ungra, Taskmaster Gurran, and Ankova the Fallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34738] = { id = 34738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullin' Void", description = "If I'm reading their spells correctly, it seems that these Shadowmoon orcs are opening portals to bring prisoners here to the slave camps. Brilliant magic, really.\n\nUnfortunately, it is easily nullified.\n\n<Khadgar places a small rune in your hand.>\n\nThis rune will deal with their void magic. Activate it near their portals, and they will instantly be nullified.", objectives = "Close 10 Shadowmoon Portals by using the Rune of Endless Ravening near them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34739] = { id = 34739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowmoon Clan", description = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, {name}.", completion = "You fight exceptionally well, {name}... better than I could ever hope to.\n\nWith those orcs out of the way, Khadgar and Maraad should now be able to safely guide the rest of our group through the cave.", objectives = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34740] = { id = 34740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel", description = "Forgive me if I'm a bit flustered - I've never killed anyone before.\n\nMy name is Yrel, and I am a student of Karabor.\n\nYou say you have an ARMY with you? The Light must truly be watching over me today.\n\nI will follow you, then. Lead the way, {name}.", completion = "Up there - that is Keli'dan the Breaker. No doubt he's been alerted to our presence, and he's attempting to tell his warlord about our little jailbreak.\n\nWe have to take him out, {name}.", objectives = "Escort Yrel to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34741] = { id = 34741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keli'dan the Breaker", description = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him.\n\nI will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", completion = "Fine job in the cave, but this is no time to rest.\n\nWe have momentum. We must stay in motion.", objectives = "Slay Keli'dan the Breaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34742] = { id = 34742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Blackrock Spire Challenge Mode - Consolation (Nth)" }
quests[34743] = { id = 34743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: The Crystal Blade of Torvath" }
quests[34746] = { id = 34746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shields Down!", description = "Did you hear that? They got the shield up. There'll be no getting into Telaar now.\n\nYou must get that shield down. The only way to do it is to destroy the Arkonite crystal.\n\nDon't worry about me. You're going to kill two birds with one stone; Packleader Kargora is the one who stole your blueprints.", progress = "Good news?", completion = "Perfect! You retrieved the blueprints.\n\nThere's only one thing left to do.", objectives = "Destroy the Arkonite Crystal and Collect the Garrison Blueprints from Packleader Kargora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34747] = { id = 34747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honor of a Blademaster", objectives = "I am without a clan. The Burning Blade are dead to me. Perhaps someday I will create a clan of my own.\n\nIn the meantime, it would be an honor to fight at your side. You freed me and fought well.\n\nThere is much we could learn from each other. What do you say?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34751] = { id = 34751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear!", description = "You gotta help me fix this robot. I'm friggin' hungry!\n\nI built the Pleasure-Bot 8000 to locate Draenor truffles, and what does it do? It swims to this stupid island and shorts its power fluctuator.\n\nI got it hooked up to these batteries, but it ain't enough juice to jump it.\n\nBe a doll and get me the zapper sacs from the electric eels in the lake, would ya? They oughta be enough.", progress = "You got the stuff, buddy?", completion = "Yeah, that's the stuff! You're a good business partner, considering you're a {class} and all.\n\nNow let's just mash these into this port...", objectives = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34755] = { id = 34755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mining Captain Bashgar" }
quests[34756] = { id = 34756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Charming Deception", description = "Reshad is more than he appears; a mottled old crow with his beak in a book, certainly, but we need him.\n\nShadows gather beneath the lonely spire, in Veil Terokk. Reshad must make it there safely.\n\nAlong the path you'll find charms primed with illusion spells. You need only touch them to take on Reshad's image.\n\nAdherent assassins are on the prowl for an old outcast with scrolls on his back. They will fall upon you.\n\nOh, but won't they be surprised when the illusion fades?! Kee-hee-hee!", completion = "How very noble of you to act as bait on my behalf. I will not forget this.", objectives = "Use 5 Illusion Charms to draw out Adherent Harriers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34758] = { id = 34758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking For Help", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Head southeast and see if you can find anyone on the shoreline.", progress = "You think I am going to help you?", completion = "Time to see what you can do.", objectives = "Find a local fisherman that can help our cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34760] = { id = 34760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Warchest of Kull'krosh" }
quests[34761] = { id = 34761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear!", description = "Oh, the gnomanity!\n\nThe Pleasure-Bot 8000 broke before it could bring me a single Draenor truffle. It swam here and shorted its power fluctuator.\n\nAGAIN!\n\nI have power going to it, but it isn't enough to override the fluctuator.\n\nCould you get me the sacs from the electric eels in the lake? I think that would be just the ticket!", progress = "Do you have the eel sacs?", completion = "Those look perfect! By all that is mechanical, this had better work.\n\nNow let's just insert these here...", objectives = "Collect 6 Zapper Sacs from Lakebottom Zappers in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34765] = { id = 34765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Den of Skog", description = "So this gronn infestation ain't gonna solve itself. You're gonna have to show them who's boss, Horde style!\n\nWith this many gronnlings around there is bound to be a full grown, big mama of a gronn. Find him... it... her... or whatever, and take it out, and the rest of those gronnlings might lose interest in our little operation here.", progress = "You find that big gal... or guy... or gronn? Really, I ain't sure what to call them.", completion = "Little known fact, old gronn grottos make for great farming soil.", objectives = "Kill Skog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34766] = { id = 34766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logistical Nightmare", description = "Commander, I am afraid I have... troubling... news.\n\nThese saberon followed our encampment from Gorgrond, and have been stealing our supplies, ransacking our ledgers, and slaughtering our peons!\n\nI hate to ask of your time to deal with the matter, but all of our men are stationed guarding the camp from any further raids. We desperately need those supplies so we may enact your will!", progress = "Commander! Have you had time to locate our supplies and ledgers?", completion = "I never doubted you for a moment. You are truly a commander of the people.\n\nLok'tar ogar!", objectives = "Retrieve 5 Sacks of Supplies and 5 Garrison Records.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34769] = { id = 34769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Choice to Make", description = "We're just about ready to go here. All that's needed now is for you to make your choice.\n\nTake a look at the blueprints on the drafting table.\n\nAre we going to construct a corral or a tankworks?", completion = "This is a momentous occasion, commander. I'll have Thaelin and his people get to work right away.\n\nYou'll see; this decision is going to be critical in our efforts against the Warsong.", objectives = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34770] = { id = 34770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Honor of a Blademaster", objectives = "I am without a clan. The Burning Blade are dead to me. Perhaps someday I will create a clan of my own.\n\nIn the meantime, it would be an honor to fight at your side. You freed me and fought well.\n\nThere is much we could learn from each other. What do you say?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34771] = { id = 34771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Stuff" }
quests[34772] = { id = 34772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morkeths Cage" }
quests[34773] = { id = 34773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why Is The Brew Gone?", description = "Commander, we have a bit of a... uh... problem.\n\nThis group o' saberon followed us from Gorgrond, and they've been stealin' our footmen's swords an' slaughtering our peasants!\n\nI hate to ask fer your time, but all of yer men are guardin' the camp from any further raids. Plus...\n\n<Quartermaster O'Riley lowers her voice to a whisper.>\n\nThey took our beer!", progress = "Commander! Have ye had a moment to deal with the saberon?", completion = "Oh thank goodness, I knew ye would come through!\n\nAt your service, as always.", objectives = "Retrieve 5 Footman Longswords and 5 Thunderbrew Kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34774] = { id = 34774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 5000", sourceObjective = "You will accept this gift, and you will like it.  To do otherwise will automatically engage my organic incineration weapons.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[34775] = { id = 34775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Probable", description = "Despite his recent captures, Olin Umberhide seems to be a tauren of some skill in combat. He certainly has learned how to get an enemy's attention.\n\nI have a mission available that might prove ideal for his skill sets.\n\nWhen you are ready, simply issue the order via the command table in front of me and we will dispatch him immediately.", progress = "Commander, I have a mission that might suite your new follower quite well.", completion = "As additional missions come to my attention I will make them available here.", objectives = "Use the Command Table to send Olin Umberhide on a mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34776] = { id = 34776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatekeepers of Auchindoun", description = "I was taken captive by the Iron Horde when they raided our caravan en route to Auchindoun.\n\nI escaped, but these spirits won't let me through to join my fellow Sunsworn until someone defeats them in combat!\n\nPlease, will you help me defeat them?", progress = "I appreciate all of your help, hero.", completion = "Thank you, {name}. I am truly in your debt.\n\nWhen I fulfill my duties to Lady Liadrin I will come find you.", objectives = "Defeat Vindicator Dalu and Soulbinder Halaari in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34777] = { id = 34777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gatekeepers of Auchindoun", description = "Auchindoun is under attack, stranger, and I intend to help defend it.\n\nThe only problem is the only armor I could find was my grandfather's old set, and it isn't nearly enough to defeat the spirits blocking the path toward Auchindoun.\n\nWould you defeat them and let me through the gate with you? I will find a way to repay you!", progress = "I will defend Auchindoun with my life. We cannot lose anymore in this war!", completion = "You have my eternal gratitude, hero. I will find a way to repay you someday.", objectives = "Defeat Vindicator Dalu and Soulbinder Halaari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34778] = { id = 34778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Migrant Workers", description = "{name}, more recruits arrive at your garrison every hour. We will soon run out of food.\n\nI have made contact with Exarch Akama in hopes of securing rations from Elodor, the breadbasket of this valley. He has agreed, provided we supply labor for the harvest. Everyone wins.\n\nIf you agree with my plan, speak with Foreman Zipfizzle here in the courtyard - he has gathered together available laborers. Akama and I will escort them and meet you at Elodor, far to the east!", progress = "Where's the rest of the caravan?", completion = "You made it!\n\nBut... one of our wagons didn't. Have you seen Maraad? He's still out there somewhere.", objectives = "Speak with Foreman Zipfizzle in your garrison, then meet with the laborers outside of Elodor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34779] = { id = 34779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Circle the Wagon", description = "One of our wagons fell behind, and disappeared somewhere in the woods to the northwest. Vindicator Maraad and several of your workers are stranded out there.\n\nFind them and bring them back!", progress = "Did you find them? Check the woods to the northwest. If I know Maraad, he probably tried to take the shelter of a hill.", completion = "I am keeping the sickles. They remind me of a lesson so many of us draenei forget - that the Light lives in every farmer as much as in any priest.\n\nYou fight well, and I am pleased to call you friend. Your laborers will be safe here in Elodor. If you are not convinced, speak to Exarch Hataaru here. His devices secure all the draenei strongholds.", objectives = "Find Maraad and the lost laborers and escort them back to Elodor Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34780] = { id = 34780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invisible Ramparts", description = "Exarch Akama is too cautious, but we shouldn't ignore a threat from the Shadowmoon clan. It is good you are here!\n\nSince we arrived on Draenor I have dedicated myself to recreating the technology we left behind. This large structure here is a defense ward. It should counter a Shadowmoon advance - provided we power it up.\n\nI have prepared resonance crystals at my workshop to the south. Carry one crystal at a time to the three pylons that surround the ward, then activate the control panel nearby!", progress = "<The console thrums with energy. You can't interpret anything on the display, but some of the lights are still blinking needily.>", completion = "The console thrums with energy and lights up as you draw near, as though sensing your presence. Simply touching the main panel brings the defense crystal to life outside.\n\nIf this is the kind of technology Hataaru was able to cobble together from spare parts, you can only imagine the splendor of the world he came from.", objectives = "Carry charged resonance crystals to the primary, secondary, and tertiary pylons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34781] = { id = 34781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenstrations", description = "No sooner does power rush to the crystal outside than you hear distant war cries and shouts of alarm. Elodor is being attacked!\n\nIf you want your laborers to come home in one piece, you'd best help with the defense of the town. Defeat the invasion and then return to the control console to reset the defenses.", progress = "The sounds of attack still reverberate from outside, which is alarming, given that the console seems awash with angrily blinking warning indicators.", completion = "You saved the town! The controls shut down as you approach, but many of the indicators are still blinking frantically. Something seems wrong.\n\nHataaru yells out to get your attention outside...", objectives = "Kill 8 Shadowmoon Raiders or Dark Priestesses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34782] = { id = 34782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Exarch Council", description = "Good work at the gates! The Shadowmoon orcs have been seeking prisoners for some reason. Their aggression helps our cause.\n\nCome with me. I would like to introduce you to the Exarch Council, \"The Hand of the Prophet.\" I have been trying to convince the Exarchs to support our cause and go on the offensive against the Iron Horde, but they are - as always - too cautious and slow to act.\n\nCome with me, I will introduce you to Exarch Othaar up the hill. Perhaps meeting an Alliance hero can sway the council.", completion = "<Exarch Othaar is a towering, intimidating figure. His eyes bore into you, determining if you are friend or foe.>\n\nSo, you are {name}, esteemed {class} of this \"Alliance\" that has appeared on our shores. On behalf of the Exarch Council, I welcome you to Elodor.", objectives = "Speak with Exarch Othaar in Elodor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34783] = { id = 34783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naielle, The Rangari", description = "I am calling the Exarch Council to order to hear your petition. None of us doubt that this \"Iron Horde\" is a threat, but few can agree on what we should do about it. It is up to you and Vindicator Maraad to gather the Exarchs together.\n\nExarch Naielle is the leader of the Rangari, the \"Eyes of the Prophet.\" They are our scouts who silently stalk the farthest corners of Draenor. Seek her out in the Rangari Enclave northwest of here.", completion = "{name}! You have only just arrived but already your name is the talk of Elodor.\n\nI will gladly support your cause for the Exarch Council - it has always been my opinion that the draenei need to get out and be proactive in our world instead of hiding behind our walls.\n\nBut first, I need your help with something...", objectives = "Speak to Exarch Naielle in the Rangari Enclave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34784] = { id = 34784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun with Fungus", description = "It is our mission as rangari to explore and understand this world. Around you is the Umberfen. Many draenei lost their lives when we first discovered this place. The volatile spores burst whenever anyone approaches.\n\nBut we watched... and we learned.\n\nAround the swamp you'll notice \"Shimmershrooms,\" distinguished by their orange glowcaps. Their dust will make you invisible to the volatile spores. Grab the spores - gently! - and bring them to me.\n\nWe will forge this savage world into a weapon.", progress = "Remember, unless you are covered in shimmershroom dust, the spores will explode as soon as you get near.", completion = "Careful with those... hand them here. Wonderful!\n\nI will have my rangari bury these around the perimeter of Elodor. If the Shadowmoon orcs dare attack us again, they are in for a nasty surprise!\n\nDraenor is a hostile world, but if we take the time to learn and understand it, we can turn it to our advantage.\n\nI will finish up here and meet with the Exarch Council shortly. I will be sure to back your proposal.", objectives = "Use the Shimmershrooms to safely gather 12 Volatile Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34785] = { id = 34785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hataaru, the Artificer", description = "I will also need you to call upon Exarch Hataaru. I understand you were helping him with our defenses at the gate.\n\nHataaru is our Chief Artificer - he understands our technology better than any other and has been working tirelessly to recreate the glory of the civilization we left behind.\n\nHe has moved to his workstation outside of the Elodor Dig, our crystal mines located just to the Southeast. Look for him at the mine entrance.", completion = "Ah, {name}! I suspected I would see you again soon.\n\nI am willing to speak on your behalf at the Exarch Council, but an emergency situation has come up...", objectives = "Speak with Exarch Hataaru outside of the Elodor Dig.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34786] = { id = 34786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engorged Goren", description = "You must be the {class} that so impressed Exarch Hataaru. Can you help?\n\nThe Elodor Dig just behind me is overrun by strange stone creatures. These so-called goren actually devour minerals, metabolize them, and grow crystalline structures from their arms and back. Like most of the wildlife on this world, they completely baffle us.\n\nPlease slay as many as you can and gather their crystal scales for me. You'll be protecting our earthworkers and aiding our research at the same time.", progress = "What's the status inside the dig?", completion = "<The artificer withdraws a loop and peers intently at the scales you've brought him.>\n\nUnreal. The crystalline matrix is flawless, as if produced from one of our forges on Argus.\n\nI wish we could hook up these creatures to our machinery... but I suspect the Exarch would take issue with that.\n\nThank you for your help!" }
quests[34787] = { id = 34787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exarch Maladaar", description = "The council is almost assembled: Othaar, myself, Hataaru and Naielle are ready. Only Exarch Maladaar remains. He has not been himself since he returned from his capture at the hands of the Iron Horde... but Vindicator Maraad was able to track him down.\n\nFind Maladaar at the Fey Landing, just south of the town center.", completion = "{name}, my Alliance friend from Tanaan! I have not forgotten my debt to you.\n\nI will do everything in my power to convince the council to support you in every way possible. However...\n\n\n\nI have grave concerns about our safety here.", objectives = "Speak with Exarch Maladaar at the Fey Landing south of Elodor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34788] = { id = 34788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend of the Exarchs", description = "Only three members remain of the Exarch Council, but we are all deeply indebted to you. The vote is unanimous: Your Alliance will have our full support on Draenor.\n\nWe are also going to place a draenei representative under your direct command. Three potential candidates are here in the courtyard. Speak to them and choose who you want - we will dispatch him or her immediately to your garrison!", progress = "Who are you going to pick, {name}?", completion = "An excellent choice! We'll send your pick directly to your garrison to help with any missions you encounter.\n\nNow, about those supplies you requested...", objectives = "Choose a follower (either Andren, Chel, or Onaala) and then speak with Exarch Naielle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34789] = { id = 34789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaker for the Dead", description = "This was a betrayal from within. There's no other explanation for it. None of the Exarchs trust each other now - especially me. But Othaar and Akama can damn their laws. We've got to rout out the traitor and the only way to do it is to speak to the corpse!\n\nJoin me just outside the Altar of Sha'tar atop the eastern cliffs. Soulbinder Nyami and I will perform an exorcism to save Hataaru's immortal soul... and maybe learn who did this to him.\n\nDo you trust me, {name}?", progress = "Exarch Hataaru didn't deserve to die that way. Not like this.", completion = "One of the five Exarchs is dead. Another is a traitor. Dark times.\n\nWe will end this here and now. Can I count on you for one final task?", objectives = "Meet Exarch Maladaar at the cliffs east of the Altar of Sha'tar. Complete the ritual to cleanse and interrogate Hataaru's corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34790] = { id = 34790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sting", description = "The exarchs seem to trust you, {class}. Are you venturing into the Umbrafen?\n\nThe Sporebats in this area are usually docile, but something's got them all riled up. When they attack, their stingers wrap around exposed limbs. I've seen them tear through reinforced leather like it was paper. How do they work, I wonder?\n\nCould you bring me a pristine sporebat stinger? I'd love to study it.", progress = "Most draenei avoid the Umbrafen, but we rangari seem drawn to the most dangerous places - that's where you really learn how the world works.", completion = "Would you look at that - the entire tentacle is barbed. Uggh. No wonder the wounds they inflict tend to get infected. We could learn something from this. I wonder if rangari explorers should start equipping themselves with whips?\n\nThank you, {name}. This Alliance that you come from must be quite the collection of heroes!", objectives = "Acquire a Pristine Sporebat Stinger from a Moonglow Sporebat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34791] = { id = 34791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning the Exarchs", description = "You set the book ablaze, but not before noting its contents. The demonic tome was dedicated to enchanting weapons with fel energy. It looked as though the goal was to ensnare the victim's soul.\n\nThe Exarchs must be warned that traitors are among them! The Council should be meeting now just up the hill to the east.", completion = "Dead! Exarch Hataaru is dead! His body was discovered moments ago, stabbed in the back. The weapon that killed him was fel in origin. Tell me everything you know.\n\n<Maladaar nods as you describe what you found.>\n\nYes. The traitors wanted to capture Hataaru's soul. Someone wants something he knows, dead or alive... We must act at once.", objectives = "Talk to Exarch Maladaar at the Altar of Sha'tar in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34792] = { id = 34792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Traitor's True Name", description = "We must give the traitor no place to hide. I have a focusing lens that will illuminate cloaked fel energy. If it were placed on a high point, it could act like a beacon, lighting up anyone in town who reeks of the fel taint.\n\nThere is a prayer circle atop the Exarch's Rise to the north that will serve our purpose. Plant the focusing lens, {name}. If you reveal anything, deal with it. Then meet me below.", progress = "What happened up there?", completion = "<The Exarch listens to your tale, his face contorting into concern, grief, and finally anger.>\n\nSo Othaar has lost his way. \"Socrethar\" he calls himself now. At last we have our answer. I fear my capture at the hands of the Iron Horde was his doing. There may be other traitors amongst us - I must hurry back to Auchindoun and make sure we are safe.\n\nIn the meantime, I believe the Exarchs owe you a decision...", objectives = "Plant the Focusing Lens atop the Exarch's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34793] = { id = 34793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchenai Defenders Greeting" }
quests[34794] = { id = 34794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Fight to Nagrand", description = "Boss-mon, good to see ya.\n\nDurotan recommended dat we be gettin' a foothold in Nagrand, so I taken the liberty of dispatchin' some of da boys.\n\nThrall's already reportin' that the outside be nearly complete. He been askin' me to let ya know they be ready for ya.\n\nA windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, <sir/ma'am>.", completion = "They came at us... from... nowhere.\n\n<The stoneguard nearly passes out.>", objectives = "Speak with Stone Guard Brox at the caravan in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34795] = { id = 34795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Warsong", description = "<The officer is in a great deal of pain. It's clear that he's not long for this world.>\n\nThe Warsong. Surprise attack.\n\nHeaded into... the Burning Blade....\n\n<He takes a moment, before continuing.>\n\nThey took the... blueprints....\n\n<These are his last words.>", completion = "Commander {name}. It's good to see you. We have much to discuss.\n\nThe situation in Nagrand is rapidly deteriorating. The Warsong clan is on the move.\n\nTo make matters worse, Grommash has named Garrosh their new warlord.", objectives = "Speak with Thrall at Wor'var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34801] = { id = 34801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilgrimage Gone Awry", description = "I am a humble pilgrim, I swear. Please don't hurt me!\n\nMy sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, you have to help me. I'm desperate. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back. I just know it....", progress = "Tuliaa isn't just my sister. She's my best friend.", completion = "Thank you, stranger.", objectives = "Gather 6 Prowler Blood, 6 Snapdragon Fronds, and a Riverhopper Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34802] = { id = 34802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pilgrimage Gone Awry", description = "My sister and I were traveling to Auchindoun to pay our respects to my grandmother when we hit an overturned rock and lost control of our caravan. I managed to survive, but my sister...\n\n<Nadur cries.>\n\nPlease, I need your help. If you could bring me some prowler blood, snapdragon flowers, and a riverhopper eye, I can fashion a potion to bring her back... I just know I can...", progress = "I don't know what I would do without Tuliaa... she's not just my sister. She's my best friend.", completion = "Thank you, a thousand times thank you.", objectives = "Gather 6 Prowler Blood, 6 Snapdragon Fronds, and a Riverhopper Eye.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34803] = { id = 34803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Them Running", description = "Your scouts have located the saberon's alpha male just outside our gates!\n\nCommander, I believe that dispatching this target will send any of these remaining vermin running back to their caves.\n\nI do not wish to ask more of you, but you are the only one capable of this task, <sir/ma'am>.", progress = "Is the alpha male dispatched?", completion = "For {name}! For the Horde!", objectives = "Slay Vicegnaw just outside Vol'jin's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34804] = { id = 34804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In Your House", description = "<Sir/Madame>, we have located the saberon's alpha male just outside our gates!\n\nWe believe that slaying him will send any remaining saberon running with their tails between their legs, but the beast is positively massive!\n\nI do not wish to call upon you once more, but you are the only one capable of this task.", completion = "Victory! For the Alliance!", objectives = "Slay Ripgut just outside Fort Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34805] = { id = 34805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo Hunters", description = "I am no sorcerer, but I've picked up a few spells in my time - enough for me to pass unseen by the naked eye.\n\nUnfortunately, the vampire bats in these woods don't use their eyes. They will hear my shuffling robes and Percy's incessant clucking a mile away.\n\nClear them away from the path, would you?", completion = "Blasted things. Nothing more than flying rats if you ask me!", objectives = "Slay 10 Echo Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34806] = { id = 34806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prune the Podlings", description = "The blood soaked body of Ryan is slumped up against the cave wall. Tiny teeth marks cover his body.\n\nThe podlings clearly are a threat to you and your garrison.\n\nIt's time to do a little pruning.", objectives = "Take revenge on the podlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34807] = { id = 34807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Goldmane the Skinner" }
quests[34808] = { id = 34808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Lazy Peons", description = "We have a rare opportunity to strike at the heart of the Warsong. But, we need your wisdom and leadership.\n\nThe most important decision will be your choice between building a corral or a tankworks. This choice will setup our approach to the fight against the Warsong.\n\nThazz'ril will head up our building efforts. Will you give him a hand?\n\nIt looks like he's having trouble motivating his peons to work.", progress = "If there's one thing the Horde never seems to be short on, it's lazy peons.", completion = "I knew it was a mistake to bring these guys with me from the Valley of Trials.", objectives = "Motivate 8 Lazy Peons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34809] = { id = 34809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Mineralogy", description = "<Gazmolf gestures at the large machine nearby.>\n\nI built this machine to break down elementium minerals into base elements. You see, it's not just what's buried within the ground that can be valuable; but also the ground itself!\n\nTake, for example, the earth elementals below us; inside every earth elemental is an earthen core, dense in precious metal!.\n\nThose elementals are going to make us rich! Collect several earthen cores, place them in the Gold-O-Matic 9000, and I'll give you a cut!", progress = "<The Gold-O-Matic 9000 buzzes and whirrs with the sounds of heavy machinery.>", completion = "<The Gold-O-Matic 9000 crunches and grinds through the elemental remains.>\n\nchakk-chackk-chak-chak, chak-a-chak-akk-chk-chk-chk.", objectives = "Collect 4 Earthen Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34810] = { id = 34810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gazmolf Futzwangler and the Highmaul Crusade", description = "I'm here in Nagrand recruiting for the Steamwheedle Preservation Society. We're the archaeological branch of the Steamwheedle Cartel.\n\nWe're here to collect all of the artifacts, relics, antiquities and oddities that Nagrand has to offer! Currently, we're hiring surveyors, excavators, adventurers... you name it!\n\nIf you're interested in getting your hands dirty, talk to Gazmolf Futzwangler over at Stonecrag Gorge. He's the goblin in charge of this expedition!", completion = "It's good to see that there's still an interest out there in real archaeology!\n\nThere's a lot of misconceptions out there about how archaeology is really done, but have no fear! The great and famous Gazmolf Futzwangler is here to educate you.", objectives = "Speak with Gazmolf Futzwangler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34811] = { id = 34811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Help is Hard to Find", description = "The excavation team is on strike!\n\nForeman Thazwix and his cronies think they can squeeze the Steamwheedle Preservation Society for some extra dough by refusing to work.\n\nWhat I need is a scab, a strikebreaker; someone to put some pressure on them by doing the job they refuse to do!\n\nGo down into the gorge, dig up some antiquities for me, and I'll pay you what I would have payed those lazy numbskulls!", progress = "Do you have the Nagrand Antiquities?", completion = "Great work, {name}!\n\nThat bunch of good-for-nothing's came crying when they found out someone else was making their money! I don't think Thazwix, or his cronies, will be much trouble from here on out.\n\nAs promised, here's the pay I owe you for a job well done!", objectives = "Collect 8 Nagrand Antiquities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34812] = { id = 34812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Stables Tracking Event" }
quests[34813] = { id = 34813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde Workshop Tracking Event" }
quests[34814] = { id = 34814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me!\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nHe's waiting at my tower. Let's leave immediately and introduce you to one another.", progress = "You are {name}, I presume?", completion = "I am Magister Krelas. Pyromaniac.\n\nPleasure.", objectives = "Follow Archmage Khadgar and speak with Magister Krelas in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34815] = { id = 34815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Acquaintances", description = "It's nice to see someone else taking a vested interest in the arcane arts, you know. It's all too rare these days if you ask me.\n\nUnfortunately, I must meet Cordana to handle an important matter, but we're in luck! One of my good friends in the Kirin Tor has agreed to help you connect your arcane sanctum to the ley line network.\n\nShe's waiting at my tower. Let's leave immediately and introduce you to one another.", completion = "Nice to meet you.\n\nI am Magister Serena. Frost mage extraordinaire!", objectives = "Follow Archmage Khadgar and speak with Magister Serena in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34817] = { id = 34817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altar Altercation", description = "Save the prisoners from the Altar.\n\n[NOTE: THIS QUEST WILL GET SIGNIFICANT REVAMP ONCE WE GET THE ALTAR IN]" }
quests[34818] = { id = 34818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Lantresor of the Blade", description = "The garrison blueprints were taken to the Burning Blade village when the Warsong sacked your caravan. I can't construct this building without those plans.\n\nThere's been talk of a young blademaster who's been exiled from the clan for many years. They call him Lantresor of the Blade.\n\nOur scouts recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you recover the blueprints?", completion = "Who are you?\n\nDon't you know death by sight, {class}?", objectives = "Find Lantresor of the Blade in Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34819] = { id = 34819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruitful Ventures", description = "Oh no! They must be vegetarians.\n\nWhat these elekk need is fruit and lots of it. There are cherries all over the place around here under the trees.\n\nYou wouldn't mind grabbing me some, would ya?", progress = "I heard the worst rumor about how you have to obtain those things.\n\nSomething about talbuk first eating them and then 'processing' them, and then... well, I don't want to talk about it.", completion = "You got them all? I just know this is going to work.", objectives = "Collect 15 Nagrand Cherries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34820] = { id = 34820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lumberjacks", description = "Shelly and her crew haven't returned from Gloomshade Grove.\n\nIt's been days... I hope everything is okay.", completion = "This is one of the pack mules Shelly and her crew took to Gloomshade Grove.", objectives = "Find out what happened to Shelly and the missing lumberjacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34821] = { id = 34821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar Summon" }
quests[34822] = { id = 34822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Need", description = "I heard you guys hijacked and wrecked a ship on your way out of Tanaan.\n\nIt's like my daddy always said: One man's wreck is another goblin's workshop.\n\nYou should head down to the coast west of the garrison and see if you can't find any materials we might salvage. Oh, and uh... should probably watch yourself. I hear there are ogre raiders in the area.", progress = "How's the salvage operation comin'?", completion = "Hey... now that is some nice salvage. Say what you will about the Iron Horde, but they got some serious raw materials to work with.", objectives = "Collect 10 Drudgeboat Salvage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34823] = { id = 34823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ogron Live?", description = "Commander, our Frostwolf allies reportin' dat the Bladespire ogres have an outpost to our west led by an ogron.\n\nI heard tales of da ogron but never seen one. Dey be brutes, creatures from a time that was best left forgotten. Dey say most were slain during the forming of the original horde. What dey lack in wisdom they make up for in violence, force, and greed.\n\nI counsel dispatchin' dis creature as soon as possible.", progress = "Where the ogron goes, death and pain are sure to follow.", completion = "Well done, boss-mon. The Bladespire ogres been pullin' back their raiding parties. But ya can bet dey be comin' back, and in larger numbers. The threat from their citadel must be dealt with soon.", objectives = "Slay Groog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34824] = { id = 34824, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Got", description = "Every fortress needs three things.\n\nOne: peons! Find Skaggit and have him get our peons back to work.\n\nTwo: building materials. I had the peons set up a cache for you where they will store resources they create while you are away. You should check it out.\n\nAnd three: raw experienced muscle! Constructing buildings in a garrison can take some time but I think we can speed up your first building by hiring Skaggit's recently promoted Senior Peon II. Find him and tell him I sent ya.", progress = "If buildin' a stronghold were easy, everybody'd be doin' it.", completion = "Yeah, that's the stuff. Lumber, stone, peons, more peons. It's like we are building you a stronghold or something.", objectives = "Have Skaggit get the peons working, investigate your Garrison Cache, and find Senior Peon II.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34825] = { id = 34825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gruuk" }
quests[34826] = { id = 34826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Friend of My Enemy", description = "Hallvalor is the ancestral home of the Burning Blade clan. Since they're such fast friends, the Warsong have allowed the blademasters to remain in Nagrand.\n\nWe are fierce, but we won't win if the Burning Blade attack us. It would be wise to strike first.", completion = "A great victory over the Burning Blade!\n\nThis new Warlord Azuka Bladefury sounds formidable. We will have to keep an eye on her and her blademasters.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34827] = { id = 34827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last of the Talonpriests", description = "Talonpriests live among us in secret, guarding the rites of the Talon King's return.\n\nThe Adherent proclamation you acquired in Skettis revealed two of them living in the Shadowglade to the north. Orcs have moved into the region, and the Adherent's beam weapon left Veil Akraz a smoking crater.\n\nAs you can see, my people are beset by enemies on all sides.\n\nTalonpriest Ishaal survived and is in hiding. Drink this elixir near his hut to peer into the shadows and make contact with him.", completion = "Hm, not what I was expecting when I heard that Iskar was sending help.\n\nNo matter. You'll have to do.", objectives = "Drink the Elixir of Shadow at Ishaal's Hut in the Shadowglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34828] = { id = 34828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ishaal's Orb", description = "The Adherents came for me, but I was already hiding. I watched from the shadows as they ransacked my hut.\n\nThen I watched the Shattered Hand orcs arrive and butcher them like dinner fowl. Seems everyone is after us these days.\n\nOne of those orc thugs made off with my scrying orb. I will be needing it back if I am to be of any use to Iskar.", progress = "Have you found the orb?", completion = "Hmm... something's not right. She's been tampered with.\n\nSomeone else has used my orb to enter the realm of shadows.", objectives = "Retrieve Ishaal's Orb from Camp Thornscar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34829] = { id = 34829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Neighbors", description = "The Shattered Hand clan is made up of orcs who can call no other clan home. They are sadistic warriors who maim their bodies, perhaps in a show of solidarity or perhaps because they simply enjoy the pain.\n\nIt does not matter. What matters is that they are expanding their territory, butchering anyone in their path.\n\nThey must be dealt with.", completion = "Blood for blood, as it should be.", objectives = "Slay 15 Shattered Hand orcs in Camp Thornscar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34830] = { id = 34830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind the Veil", description = "Soon after the orcs swept in, Veil Akraz was laid to waste by a beam of light from Skyreach.\n\n<Ishaal's eyes glass over as he peers into his orb.>\n\nIt seems they missed their true target. Zellek is still there, hiding in the realm of shadow.\n\nAnd... someone else as well. The orc assassin who used my orb.\n\nTake this. Drink it in Veil Akraz and find Zellek.\n\nOh, and be careful. It's a little more potent than the last one. You'll see...", completion = "Well, you are not stabbing me yet.\n\nThat is a good sign.", objectives = "Drink the Major Elixir of Shadows at Zellek's hut in Veil Akraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34831] = { id = 34831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encounter Mushroom" }
quests[34833] = { id = 34833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prune Ancient" }
quests[34834] = { id = 34834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Commentary" }
quests[34835] = { id = 34835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather Energy" }
quests[34836] = { id = 34836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunarblossom", description = "How I long to hold Kat'la.\n\nNo star or moon can compare to her beauty.\n\nAlas, I am but a simple boar farmer.\n\nIf only I could find time to sneak away from this pathetic excuse for a job and pick some lunarblossoms for Kat'la.\n\nI wouldn't dare confess my love to her without a gift.", progress = "How can I help you, {class}?", completion = "Lunarblossoms! You are too kind! I can't wait to give these to Kat'la.", objectives = "Pick 5 Lunarblossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34837] = { id = 34837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going to the Gordunni", description = "We have a good supply of jovite in the arsenal now but there just isn't enough of the material in the mine to keep us in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", completion = "I crafted a few things before we left that we may need: some bombs, a grappling hook, even was able to get one of the goblins to get a spare rocket pack.\n\nI'm sure we'll find a use for everything.", objectives = "Travel to Gordal Fortress and meet up with Morketh Bladehowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34838] = { id = 34838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ikky's Egg", description = "<Miraculously, this single egg has eluded the ravagers.\n\nA small tag has been lovingly tied around the base of the egg. It reads \"Ikky.\">", completion = "<The hatchling springs immediately to flight, then looks at you expectantly and cheeps.>", objectives = "Help Ikky hatch from the Kaliri Egg in Shadowglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34839] = { id = 34839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skog" }
quests[34840] = { id = 34840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our artillery gunners back at the arsenal.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", completion = "Now that we're inside we have much to do.", objectives = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34841] = { id = 34841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ice-Covered Supplies" }
quests[34842] = { id = 34842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Den of Skog", description = "Olin Umberhide appears to have discovered the parent of the gronnlings and is outmatched by himself. He will be slain without help.You will learn:", objectives = "Kill Skog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34843] = { id = 34843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Chillfang" }
quests[34844] = { id = 34844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Require More Resources", description = "So what we got here is a good start, but you are looking for something that can support ARMIES!\n\nTruth is, we ain't building anything without the materials to build it, and our supplies from Azeroth are limited.\n\nI got some ideas on how to get you started but you are going to have to keep your eyes open for more materials when out in the field. Lots of useful stuff out there we can change into usable material.", sourceObjective = "Gather 50 Garrison Resources.", sourceObjectiveStatus = "unverified-source-field" }
quests[34845] = { id = 34845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lurking in the Shadows", description = "There are reports of Shadowmoon clan members lurking around the ruins by the shore.\n\nThis is a popular spot for young lovers to gaze at the stars and confess their affection for each other.\n\nAs you can see we are not a village of warriors.\n\nI will pay you handsomely if you go to the ruins and make sure the Shadowmoon orcs keep their distance.", objectives = "Kill Shadowmoon Disrupters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34846] = { id = 34846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Fight", description = "We have an accessible fishing spot here, but no bait seems to work!  We need to find a local fisherman with some knowledge of the area to help us out.  Think you are up to the task?", objectives = "Find a local fisherman that can help our cause.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34847] = { id = 34847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Love", description = "My son, Kral'za, is beyond stubborn. \n\nAfter we split from the Shadowmoon Clan he refused to let go of his relationship with a young Shadowmoon orc.\n\nI forbid him to see her anymore. He ran off earlier today and has not returned. \n\nI don't trust Dol'mak. Like the other Shadowmoon orcs she continues to dabble in the void.", completion = "Aka'Magosh, {class}. I knew that void witch was no good.", objectives = "Find Kral'za.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34848] = { id = 34848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Even the Odds", description = "[TEMP] The Shattered Hand orcs are using their prisoners as living training dummies. Let's even the odds and give them some weapons.", objectives = "Find Shattered Hand weapons and give them to Battered Frostwolf Prisoners or Battered Karabor Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34849] = { id = 34849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}. Then, I'll break myself free.", progress = "A blademaster without a blade is no blademaster at all.", completion = "If you can defeat Luhk, then perhaps there's some hope for you after all.", objectives = "Retrieve Lantresor's Blade from Instructor Luhk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34850] = { id = 34850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", progress = "Do you have my banner?", completion = "I don't expect you to understand the importance of what you've done.\n\nPerhaps one day you will.", objectives = "Find the Blademaster's Banner in a Burning Blade Locker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34851] = { id = 34851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gruuk", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent." }
quests[34855] = { id = 34855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", progress = "We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", completion = "Now with the viziers gone the whole Gordunni enchantment trade with the Iron Horde will come crashing down!\n\nWe can now turn our attention to dealing with Morkurk.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34856] = { id = 34856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gok Tracking Quest" }
quests[34857] = { id = 34857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag: Orcs Kicked Out of Cave" }
quests[34858] = { id = 34858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Repossessions", description = "The Gordunni were given copies of my blades as a gift from the Iron Horde. But what do they use them for? Toothpicks!\n\nSure the blades are low grade copies but it's still MY design and I can't stand to think of them in those ogre hands for a moment longer!\n\n<Sir/Ma'am>, While we are in here can you do me a favor and get those blades out of their hands!", progress = "Were you able to get all of my blades back?", completion = "Thank you, commander. With this another stain on my honor has been removed.", objectives = "Collect 6 Gordunni \"Toothpick's\" from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34859] = { id = 34859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: No'losh" }
quests[34860] = { id = 34860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", progress = "The goblins said that the flares would surely get their attention. I just hope it doesn't come from the hillside being blown apart.", completion = "Alright, that should be the last one we need. \n\nNothing feels as good as knowing you are stronger than your enemy!", objectives = "Recover 6 Iron Horde Shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34861] = { id = 34861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need An Army", description = "So the new warchief decided to send you Warmaster Zog to handle local operations. Zog!\n\nI heard that guy was notorious for organizing the Alliance AND the Horde to face off against the silithid at the Gates of Ahn'Qiraj.\n\nHe was a general back then.\n\nAnyway, if you go let him know about the barracks being done I'm sure he'll have some thoughts on how to put it to good use.\n\nYou can find Zog up at the town hall.", completion = "Commander, it is an honor to serve you.", objectives = "Speak with Warmaster Zog.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34862] = { id = 34862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Light the Braziers" }
quests[34865] = { id = 34865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skog" }
quests[34866] = { id = 34866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me in the Cavern", description = "It's time, {class}. Time for you to get your blueprints.\n\nTime for us to face the masters.", completion = "You made it. Good.\n\nGetting in here was nothing compared to what's to come.", objectives = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34867] = { id = 34867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Gorgrond", description = "Commander, I will leave my forces to secure this pass, but I will not sit idle while our enemy prepares for another attack.\n\nI want to take the fight to the heart of the Iron Horde at Blackrock, and to do that we are going to need to go where few orcs dare tread.\n\nGorgrond.\n\nIt is a savage place, filled with giants and monsters of every sort.\n\nWill you dare these wilds with me so that we might strike at the foundries of the Iron Horde?", completion = "Gorgrond is no place for armies, commander. We are now stepping into the domain of legends.", objectives = "Meet Durotan in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34868] = { id = 34868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your blueprints and your life. Or, you will be dead.", progress = "Do you have the garrison blueprints, commander?", completion = "The garrison blueprints. Outstanding.\n\nThere's only one thing left to do.", objectives = "Survive the Burning Blade's trial by combat and retrieve the Garrison Blueprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34869] = { id = 34869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tastes Like Chicken", description = "You got a moment, <bub/beautiful>? I've got an elekk-sized problem.\n\nSomeone, um, sold me... yeah, sold me these two, but they're sick. I've tried everything, but nothing I do makes any difference!\n\nI think they must be starving. I heard that elekk like raw windroc. Gross if you ask me.\n\nAnyway, while you're out doing your thing, you mind picking me up some bird meat?", progress = "Windrocs? Yeah, Nagrand's filthy with them.\n\nThey seem to like high places and rock outcroppings.\n\nI don't know. What do I look like - a windroc whisperer? You're the {class}.", completion = "It sure doesn't smell like chicken!\n\nOkay, okay, hand it over. I'll feed them and then everyone will be happy and I can turn a tidy - er, um... they'll feel better.\n\nYeah.", objectives = "Collect 10 Raw Windroc from windroc in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34870] = { id = 34870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. He's the one that set up the Iron Horde trade and, even worse, my former boss gave him one of my best maces!\n\nWe got to get my mace back! I mean... we need to kill him to secure the jovite for your arsenal!\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to dodge an attack quickly or something.\n\nAlso, if you happen to find my mace I'd like to get it back.", progress = "Do you have my mace?", completion = "Fine work commander! Your combat skills are clearly second to none. I am honored to be your armorer!\n\nLet's get back to the outpost so we can take stock of our new inventory. I saved a few flares to call us in a ride back.", objectives = "Defeat Witch Lord Morkurk within Gordal Fortress and obtain \"Fury of the Forge\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34871] = { id = 34871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Recovery Tracking" }
quests[34872] = { id = 34872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Repossessions Tracking" }
quests[34873] = { id = 34873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Through Tracking" }
quests[34874] = { id = 34874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next Steps", description = "You are positively on fire!\n\nWe have everything I need to create the scroll. Your arcane sanctum will be brimming with arcane energy in no time.\n\nI will teleport to Vol'jin's Pride to combine the reagents and marshal your forces. Meet me there when you can.", completion = "Your forces burn with passion for your cause.\n\nNot easy against such towering foes. Well done.", objectives = "Speak to Magister Krelas at Vol'jin's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34875] = { id = 34875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next Steps", description = "We did it! We have all of the reagents for the scroll. Your arcane sanctum will be the talk of Draenor before long.\n\nI'll go back to Fort Wrynn to finish it and gather your men. Meet me there.", completion = "Now we can tackle getting that artificial nexus for your tower.", objectives = "Speak to Magister Serena at Fort Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34876] = { id = 34876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loola's Lost Love", description = "Oh it was horrible.\n\nMy husband and I were fishing in the marsh, I fell asleep and when I woke up he had been turned into a toad!\n\nI'm sure it was one of those Shadowmoon orcs I hear so much about.\n\nHe jumped into the muddy waters before I could catch him.\n\nWill you help me find my lost love, {class}?", completion = "Hmm... I'm sure one of these toads is my husband.", objectives = "Search Loose Mud for Old Loola's husband.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34877] = { id = 34877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Removing the Reinforcements", description = "My own investigations have uncovered a permanent arcane portal from here to Highmaul itself.\n\nIt is guarded but shouldn't be too hard to disrupt once you've gotten some breathing room.", completion = "Excellent.  I doubt they will rebuild it after we've completed all of our objectives here.\n\nThis place will return to being a failing outpost for the Gorian Empire.", objectives = "Destroy the Portal to Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34878] = { id = 34878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foot of the Fortress", description = "We've enkindled your forces and the scroll is ready.\n\nIt's time for phase two - stealing a nexus crystal from a heavily fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills and take what is more or less rightfully yours!", completion = "My apologies for teleporting away. It's cheating, I know.\n\nI merely wanted to put a fire under your feet to get here quickly!", objectives = "Speak to Magister Krelas at the entrance to Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34879] = { id = 34879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping In", description = "Witch Lord Morkurk is no fool.\n\nHe has catapults set up throughout the foothills leading into their compound.\n\nNo matter, I have a way to handle them.\n\nTake out the ogres guarding the siege weapons and mark them once they're clear. I'm readying a vortex spell that will handle things from there.\n\nWe'll meet just outside their gate afterwards.", completion = "Before we take on Morkurk we have some business to attend to in the fortress proper.", objectives = "Help Magister Krelas destroy 3 Gordunni Boulderthrowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34881] = { id = 34881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Earth, Wind and Fire...and Water", description = "The Elemental Plateau has become unstable, and so the cycle of rebirth must begin.\n\nIt is a natural part of our life cycle that impurities are accumulated in the elemental body over time.\n\nWhen enough contamination has taken place, an elemental will become unstable and in some cases volatile.\n\nA necessary part of rebirth is pure, living essence which can be found atop the Elemental Plateau, as well as in the body of an elemental spirit.\n\nReturn to me with the essence and we shall begin the rebirth.", progress = "Bring to me the living essences of the elements, that I may plant the seeds of rebirth.", completion = "You have done well.\n\nAlthough the Elemental Plateau is no longer stable, the cycle of rebirth will soon take place and the elements will be born anew.", objectives = "Collect 4 of each living essence from the Elemental Plateau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34882] = { id = 34882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blades in the Dark", description = "Those orcs got hold of Ishaal's orb, did they? That would explain the dangerous-looking fellow who crossed into this realm shortly before you.\n\nNot everyone handles the transition as... gracefully as you did. The oaf is still grappling with his own mind, stumbling about and muttering nonsense.\n\nSoon he will be drawn to the orb again, which would presumably lead him to Veil Terokk.\n\nBetter to take him out now while he's still befuddled.", completion = "He was a big boy, wasn't he? The fiends will make quite a feast of him.", objectives = "Slay Malrok Thornscar in Veil Akraz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34883] = { id = 34883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast of Shadows", description = "Many arakkoa died in Veil Akraz. From the outside, all seems still. Empty.\n\nBut in this place between worlds, death never goes unnoticed.\n\nStray life essence seeps through from the other side; a feast for the beings who prowl here.\n\nSlay the shadow creatures here, and gather from their corpses the fine dust they produce. I will need much of it to perform the rites of the Talon King.", progress = "You know those elixirs you have been so eagerly quaffing?\n\nThey are made of this stuff.", completion = "Good. With this much dust we can delve deep enough to reach the Talon King's refuge.", objectives = "Gather 10 Shadow Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34884] = { id = 34884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kaliri Whisperer", description = "An important contact lives in the nearby Shadowglade. He is meek, but trains kaliri of monstrous size which are quite dangerous.\n\nHe once claimed they could knock a rylak out of the sky, but I'll believe that when I see it.\n\nSkizzik is holding a valuable treasure for me. Seek him out and get him back to Veil Terokk if you can. At the very least, recover the gavel I entrusted to him.", progress = "Any word on Skizzik?", completion = "I see. Well, at least the gavel is safe.\n\nAs you may have guessed, it is another of the Talon King's relics.", objectives = "Recover the Old Gavel from Skizzik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34885] = { id = 34885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mother of Thorns", description = "<Beneath Skizzik's outstretched hand, letters are scrawled into the dirt:\n\nt h o r n\n\nm o t h e r\n\nRavagers brought in by the Shattered Hand have taken over the aviary and are breeding fast. If left alone, they could be swarming the entire area - including Veil Terokk - in a matter of days.>", completion = "Shame about Skizzik's aviary. That's where Percy came from. Skizzik wasn't interested in the \"runts\" after he started breeding the big ones full-time.\n\nTo be honest, I never liked those monstrous things.", objectives = "Slay 5 Shadeback Ravagers and the Shadeback Thornmother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34886] = { id = 34886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baby Bird", description = "<Ikky cheeps again, then begins gnawing on his foot.\n\nLooking out across the nearby hillside, you spy tiny ravager grubs inching along the grass.>", progress = "<Ikky looks up at you, foot clamped in his beak, and lets out a muffled cheep.>", completion = "<You hold the handful of grubs out, steel yourself, and prepare to chew them up as a mama bird would.\n\nThankfully, Ikky snatches them from your hand before you can proceed.\n\nApparently kaliri don't do that.>", objectives = "Gather 8 Ravager Grubs in the Shadowglade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34887] = { id = 34887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While We're in the Neighborhood", description = "Ah, the hubris of ogres.\n\nIt always backfires.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nWe can disenchant these bracelets into reagents that will no doubt be useful to your arcane sanctum. What do you think about collecting some while we're here?", progress = "Most mages discount the use of arcane dust these days, but they're wrong.", completion = "Yes, these will definitely be useful! Trust me.", objectives = "Collect 8 Gordunni Runebeads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34888] = { id = 34888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicious Viziers", description = "We're after Witch Lord Morkurk, but we shouldn't charge straight at him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are the only other capable mages left of the Gordunni, and are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out first.", progress = "I don't take chances.", completion = "Now that they're out of the way, Morkurk is exposed.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34889] = { id = 34889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orbs of Power", description = "There's a minor fire we'll need to put out before we can enact my plan.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - awfully detrimental to our scroll of mass teleportation.\n\nThankfully, no ogre would ever consider that a single enemy or two would have the gall to breach their walls.", completion = "There's nothing Morkurk can do to stop us now.\n\nWell done indeed!", objectives = "Destroy 5 Astral Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34890] = { id = 34890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Step", description = "It's time to fight fire with fire.\n\nWe have Morkurk cornered. His protections gone. Use the scroll once you engage Morkurk...\n\n...and enjoy the fireworks.", progress = "Ogres. It's always ogres.", completion = "That's what we were after.\n\nLet's get out of here!", objectives = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34891] = { id = 34891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Attunement", description = "Many shaman have sought the favor of the Throne of Elements.\n\nForming an elemental bond with the furies allows a shaman to not only know the will of the elements on Draenor, but also tap into a great font of elemental power.\n\nIf you are to discover the truth behind Gordawg's disappearance, you will need to succeed where others have failed and undertake the Ritual of Binding.\n\nFirst, you must prepare yourself. Seek out the elemental pillars upon the plateau and attune your spirit with the elements.", completion = "You have done well, {name}.\n\nBy linking with each of the four elemental pillars you have attuned your life energy with each of the elements on Draenor.\n\nYou are now ready to undertake the Ritual of Binding.\n\nSpeak to me when your work upon the Elemental Plateau is finished, and we shall begin.", objectives = "Seek out the four elemental pillars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34893] = { id = 34893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardians of the Plateau", description = "The Elemental Plateau is sanctuary to the elemental spirits of Nagrand.\n\nThe greatest among the elementals on the plateau are the guardians; mighty elemental spirits that stand watch over their domain.\n\nThe guardians are pure and mighty spirits but a disturbance in the natural balance has caused them to grow unstable, corrupting the lesser elementals around them.\n\nIn order to restore balance to the plateau, the guardians must be destroyed. Only then will the cycle of rebirth begin.", completion = "Each of the guardians you put to rest were once mighty and noble elemental spirits.\n\nIn time each shall be reborn anew through the cycle of rebirth, but Gordawg must be found and balance restored lest the plateau become unstable yet again.", objectives = "Destroy the corrupted guardians atop the Elemental Plateau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34894] = { id = 34894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Bloom", description = "Many years ago I had a life-mate, Dahaka. We were only bound a short time before she was taken from me.\n\nI have lived long, but I have never known greater pain than that day. I was young and my grief was great; the earth quaked beneath my rage. I laid her to rest upon this cliff.\n\nIt is here where I too will rest, but first a favor.\n\nA rare bloom grows in a cave within the fiery, molten earth of the plateau. It was her favorite.\n\nI would lay the flower upon her grave one last time before I die.", progress = "Do you have the Ember Blossom?", completion = "This is a fine Ember Blossom that you have brought to me. I know the danger you faced to retrieve it and I thank you.", objectives = "Retrieve the Ember Blossom from the Elemental Plateau.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34895] = { id = 34895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs Tracking" }
quests[34896] = { id = 34896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Stealthed Rangari" }
quests[34897] = { id = 34897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rangari Roundup", description = "You have a keen eye, {class}.\n\nThere are Rangari like myself hidden throughout the Nightmarsh.\n\nI need reports from each of them to ensure the area is safe.\n\nPerhaps you can help me?", completion = "Thank you for the report, {name}. We must keep a close eye on these southern wilds.", objectives = "Find the 5 Hidden Rangari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34898] = { id = 34898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ikky", objectives = "<Ikky cheeps at you excitedly.\n\nIt seems you've made a new friend.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34899] = { id = 34899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Choice to Make", description = "We're ready to start building. All that we need is for you to make a choice.\n\nThe blueprints are on the drafting table. Take a look.\n\nThen, let me know if we're going to construct a corral or a tankworks.", completion = "This is a momentous occasion, commander. Thazz'ril and his peons will get to work right away.\n\nYou'll see; this decision is going to be critical in our efforts against the Warsong.", objectives = "Use the Drafting Table to choose between the construction of a Corral or a Tankworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34900] = { id = 34900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Babies", description = "That's better, but there's still something wrong. I'm getting desperate here, {name}.\n\nCan I call ya, {name}? Great.\n\nLook, I think I have it now. I know what's wrong.\n\nThey miss their babies.\n\nYeah! When they first came here, the, uh... the bastard hunters that... abandoned them said they left the babies behind.\n\nIf we're going to save them from a life of misery, if we're going to save those babies, <under his breath> and turn a tidy profit, we've got to get them some new babies!", progress = "Look, I know these things can be stubborn, but it's all going to be worth it in the end.\n\nTrust me.", completion = "You did it, {name}! Mama, papa, and family. It brings a tear to my eye.\n\nHere, take this runty one. Now that I have the whole herd, this one's just an extra mouth to feed and won't fetch anything at market.", objectives = "Coax 5 Tenderhoof Meadowstompers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34904] = { id = 34904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal Vision" }
quests[34905] = { id = 34905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placeholder Quest" }
quests[34906] = { id = 34906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krelas Summoned" }
quests[34907] = { id = 34907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Lagoon Pool/Giant Clam" }
quests[34908] = { id = 34908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Foot of the Fortress", description = "Your forces are at the ready and the scroll is prepared.\n\nIt's time for phase two - stealing a nexus crystal from a fortified ogre compound.\n\nWe'll save the scroll to bring in reinforcements in our confrontation with the Gordunni Witch Lord. Let's meet at the base of the Gordal Foothills to head into the fortress proper.", completion = "Let's not waste any time. Gordal Fortress awaits just up this hill.", objectives = "Speak to Magister Serena at the entrance to Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34909] = { id = 34909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "While We're in the Neighborhood", description = "Ogres from the empire are known for being cold and calculating.\n\nWe are fortunate that their calculations are rarely spot on.\n\nMorkurk has been using enchanted bracelets to empower his minions with arcane strength.\n\nSince we're going to have to dispatch them anyways, we might as well get some reagents out of it.", progress = "Ah, arcane powder. Reminds me of my days as an apprentice.", completion = "They're not amazing, but I do think these have some worth to us.", objectives = "Collect 8 Gordunni Runebeads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34910] = { id = 34910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicious Viziers", description = "We can't just skate in, kill Witch Lord Morkurk, and leave.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all fiercely loyal to Morkurk, and are all respectable mages in their own right.\n\nI suspect that if we attempt to engage the Witch Lord immediately that they will rush to his aid and overwhelm us. We need to take out his lieutenants first.", completion = "Now that they're out of the way, Morkurk is exposed.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34911] = { id = 34911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orbs of Power", description = "Minor issue, I'm afraid.\n\nMorkurk has placed powerful wards throughout Gordal Fortress that will prevent any sort of mass summoning - not wonderful considering our plan.\n\nThankfully, no ogre would ever consider that a single enemy or two would attack, so we should be able to slip through their fortress relatively easily.", completion = "Destroying those wards was key to our success. Well done indeed!", objectives = "Destroy 5 Astral Wards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34912] = { id = 34912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Step", description = "We have Morkurk cornered. He's all ours now. Use the scroll once you engage Morkurk...\n\n...and enjoy the blizzard of your forces raining down on his head.", progress = "It's all come down to this moment.", completion = "Looks like Morkurk was no match for the two of us, huh?", objectives = "Defeat Witch Lord Morkurk and retrieve the Arcane Nexus in Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34913] = { id = 34913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping In", description = "Witch Lord Morkurk, the leader of the fortress, has catapults set up along the road into their compound.\n\nThat won't be a problem for us.\n\nTake out the ogres around the catapults and mark them for me. This vortex spell I have prepared will handle the rest.\n\nWe'll meet at the gate to the fortress once the catapults are gone.", progress = "I certainly hope they have more than this to stop us.", completion = "We have the scroll of mass teleportation ready, but we can't use it just yet. We must take proper precautions to ensure our success.", objectives = "Help Magister Serena destroy 3 Gordunni Boulderthrowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34914] = { id = 34914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity: Telaar", description = "We've received reports that the draenei enclave at Telaar has fallen to the Warsong.\n\nI sent a small group of shadow hunters to check on the situation.\n\nKajassa is their leader. Will you meet her there?", completion = "Glad dat Aggra send ya, Commanda.\n\nDey situation is grim, an' it's 'bout ta get grimma.", objectives = "Speak with Shadow Hunter Kajassa at Telaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34915] = { id = 34915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Help Ya Kill Dem", description = "Warsong come in an' kill de draenei rangers. No lettin' dem have dis place.\n\nYou an' me, Commanda. We gonna kill dem all.\n\nYou be distractin' dem an' I usin' me Loa ta finish dem off. You see.", completion = "Oh, dat was fun. We workin' nicely togetha, you an' me, {name}.", objectives = "Kill 12 Warsong forces at Telaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34916] = { id = 34916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blessing of Samedi", description = "Three of mah shadow huntas come here wit' me. De Warsong kill dem.\n\nWe need ta help dey souls move on. Jus' in case ya find dem first, use dis on dere bodies.\n\nIt send dere souls ta Samedi, Loa of de Grave.", completion = "Dey movin' onta a betta place. Samedi be sendin' dem on all dey missions now.\n\nDank ya, {name}.", objectives = "Use the Fetish of Samedi on the corpses of the dead shadow hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34917] = { id = 34917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shields Up!", description = "The Warsong packleader is trying to raise Telaar's shield. If Kargora does that, the Warsong will have an impervious base.\n\nSo far, they've only managed to initiate the shield. This has the undesirable side effect of protecting the packleader and her shaman at the main crystal.\n\nActivate the crystals on the perimeter of Telaar. That will force the shield to fully deploy.\n\nOnce you do that, Kargora will be exposed.", completion = "Soon de shield gonna cover all of Telaar. Den we all be trapped inside togetha.\n\nDen we go kill de packleader.", objectives = "Activate the four Telaari Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34918] = { id = 34918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shields Down!", description = "De time has come, commanda. Packleader Kargora an' de Arkonite Shield no longa protected.\n\nWe need ta kill her an' destroy de shield crystal.", completion = "I'm sorry to hear about Kajassa's shadow hunters, but we couldn't afford to let the Warsong have Telaar.\n\nWith the death of Kargora and her pack, we're one step closer to the invasion of the Warsong's home, Grommashar.\n\nOne step close to justice.", objectives = "Kill Packleader Kargora and destroy the Arkonite Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34920] = { id = 34920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Ward" }
quests[34921] = { id = 34921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cult of the Ravenspeakers", description = "These outcasts are not the only cursed arakkoa holding their ground in Arak.\n\nA curious cult has formed in worship of Ka'alu, my consort and the keeper of my brood. They are considered to be quite... odd.\n\nRegardless, the outcasts will need their help. Without the wings of the ravens, Iskar can never take his fight to the spires.\n\nTake this feather and place it in the offering basket south of here. The so-called \"Ravenspeakers\" will surely take notice.", completion = "Ah, you come to learn the truth of things.\n\nWe will need to test your dedication first, yes!", objectives = "Place the Plume of Anzu in the Offering Basket in Gnarlwood Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34922] = { id = 34922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of the Raven Mother", description = "We came here to perform the ritual of calling to bring the return of the Raven Mother. We had distributed parts of the scroll to everyone and had just begun when we were attacked by the Bloodmane. Now most of the flock has been killed and fragments lay scattered across our homeland.\n\nThe ritual was a failure but we will not allow these mongrels to break our faith. We must continue our prayers here but we would be grateful if you can recover the scroll fragments for us.", progress = "We must have all the sacred texts! We cannot afford to leave even a single one unaccounted for!", completion = "Ah! The copies of the ritual!\n\nPraise the Raven Mother!\n\nHand them to me but only one at a time. We must not risk summoning the light.", objectives = "Recover 8 Ravenspeaker Scroll Fragments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34923] = { id = 34923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmane", description = "We had just arrived and begun the service of the headless fowl when the Bloodmane attacked out of nowhere.\n\nClearly, this means that the Raven Mother wishes to test the worthiness of her children. Fear not, we are steadfast and will fervently continue our prayers regardless of what may come!\n\n<Sekara leans in and whispers to you.>\n\nAlthough, if you can get rid of the Bloodmane and their leader that would be a blessing as well.", completion = "Your strength has given us time to rest and continue our rituals.\n\nMay the Raven Mother ever keep you in her shadow.", objectives = "Slay Huntmaster Sorrowfang and 10 Bloodmane Razorclaws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34924] = { id = 34924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Egg Thieves", description = "The Bloodclaw are sadistic creatures. They have attacked the Ravenskar before and have stolen the eggs of the sacred ravens.\n\nWhile you are within the Bloodclaw lands keep an eye out for the eggs.\n\nI'll be waiting for you at the nest with as many baskets for them as I can gather.", progress = "Were you able to find the stolen raven eggs?", completion = "These poor ravens have avoided a horrible future in the Bloodclaw lands.\n\nWe will take far better care of them.\n\nThank you!", objectives = "Collect 8 Dread Raven Eggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34925] = { id = 34925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polishing the Iron Throne", description = "These stinking Blackrock cowards think they're humiliating me.\n\nThey're just making me angrier.\n\nOverseer Gotrigg, in the hut over there, carries my shackle key. If I'm going to get out of there, I'm going to need that key. Then... vengeance can begin.", progress = "You'll have to pry that key out of his cold, ugly hand.", completion = "<Ga'nar works his neck out of the shackle.>\n\nMuch better.", objectives = "Obtain Ga'nar's Shackle Key from Overseer Gotrigg in the nearby building.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34926] = { id = 34926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to High Ground!", description = "This dam is about to burst. Hopefully.\n\nFarseer Drek'Thar fights atop the peak to the south of here. You should be safe near him.\n\nDon't worry about me.", sourceObjective = "Report to Drek'thar in the Blackrock Quarry in Tanaan Jungle.", sourceObjectiveStatus = "unverified-source-field" }
quests[34929] = { id = 34929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gennadian" }
quests[34931] = { id = 34931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frostwolf Cache 04" }
quests[34932] = { id = 34932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guise of the Deceiver", description = "In a cave not far from here, there lives an old woman named Challe.\n\nI knew Challe many years ago when I was young; though as I have become old and grey, she has kept her youth and beauty.\n\nChalle was jealous of my love for Dahaka and I have long suspected that Challe had a part in her death. However, without evidence I could not bring justice against her.\n\nMeet with Challe and tell her that I am dying. Tell her that I wish to know the truth of Dahaka's fate before I leave this world.", progress = "I have not much time left. Please, discover the truth of Dahaka's death before it is too late.", completion = "Challe, that iniquitous wretch!\n\nIf only I had proof of her treachery long ago, I would have ripped the villainous heart from her chest and crushed it beneath my foot!\n\nYou have brought me the truth as I asked, for that you have my thanks.", objectives = "Speak with Challe to discover the truth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34934] = { id = 34934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Initial Defenders" }
quests[34935] = { id = 34935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "After Wall Greeting" }
quests[34936] = { id = 34936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Lady Sena's Extra Stash" }
quests[34937] = { id = 34937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Skaggit's Extra Stash" }
quests[34938] = { id = 34938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ralshiara's Demise", description = "It was said in the Journal of the Rising Sun that eating in the mornings cannot be done without harming a few eggs.\n\nThe Bloodmane matron, Ralshiara, feasts upon sacred raven eggs for her snacks. How dare she! She must die for her sins!\n\nTake the path south over the mountains to reach the accursed home of the Bloodmane.\n\nTake this trinket, it fell to us from the heavens as a sign of the Raven Mother's favor and with it you might have a chance.", completion = "Let it be known that on this day the stranger has returned victorious from slaying the feared foe of the Flock!\n\nPraise the Raven Mother!", objectives = "Kill Ralshiara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34939] = { id = 34939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declawing The Bloodmane", description = "It is written in the Scroll of Sermons to \"Bite the claw that strikes you.\"\n\nTake the path south from here that leads over the mountain to the Bloodmane valley in the west. There you will find those of their tribe who can use a primitive form of magic. Slay them and remove their paws.\n\nOnce you have obtained a few bring them back to me in the nest so that they may be offered to the Raven Mother!", progress = "It is written in the Scroll of Sermons that the Raven Mother is not patient, and neither am I.\n\nDo you have the paws of the Bloodmane for me?", completion = "Yes, these will do nicely as an offering to the Raven Mother! May she feast upon our enemies!", objectives = "Collect 6 Bloodclaw Shaman Paws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34940] = { id = 34940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Spider Dagger" }
quests[34941] = { id = 34941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Debt We Share", description = "These mortal shells that we call bodies are not ours to keep. The body is a gift of earth that must one day be returned from whence it came.\n\nThe time has come for this body to return to the elements.\n\nKnow that you have lifted the weight from an old heart, {name}. As I pass on from this realm, I do so without regret. I have fought on behalf of my people and my land, I have served the elements, and I have loved.\n\nIt would honor me if you would stay during these final moments, {class}.", progress = "When I face my ancestors in the realm of spirits I will do so without shame or fear, for I have lived an honorable life.", completion = "Gar'rok was a loyal keeper and a true friend. He will be missed, but so is the cycle of life on this world.\n\nIn time we will call a new keeper of the elements, and he will serve us as Gar'rok did before him.", objectives = "Speak with Gar'rok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34942] = { id = 34942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back from Beyond", description = "We must begin preparations for the Talon King's return.\n\nFrom within this realm, I can travel quickly to Veil Terokk.\n\nYou, however, should be returned to the other side. You are powerful, and will attract unwanted attention.", completion = "Excellent work. Ishaal and Zellek have already begun the rites.", objectives = "Speak with Shadow Sage Iskar in Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
